     1	import type {AddressInfo} from 'node:net';
     2	import {WebSocket} from 'ws';
     3	import type {Express} from 'express';
     4	import {createServer} from './createServer.js';
     5	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
     6	import {answeringOrchestrator, delegatingTo, tearDown} from './wsTestSupport.js';
     7	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
     8	import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
     9	import {setLogger} from '../shared/logger.js';
    10	
    11	// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.
    12	
    13	interface Frame {
    14	  type: string;
    15	  sessionId?: string;
    16	  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
    17	  code?: string;
    18	  message?: string;
    19	}
    20	
    21	const servers: Array<ReturnType<typeof createServer>> = [];
    22	const clients: WebSocket[] = [];
    23	const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
    24	
    25	beforeEach(() => {
    26	  logLines.length = 0;
    27	  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    28	    void logLines.push({level, category, message, fields});
    29	  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
    30	});
    31	
    32	afterEach(async () => {
    33	  await tearDown(servers, clients);
    34	  setLogger();
    35	});
    36	
    37	const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
    38	  const hal = createServer({
    39	    app: (() => undefined) as unknown as Express,
    40	    wsAuth: async () => ({id: userId}),
    41	    sessionStore: store,
    42	    orchestrator: answeringOrchestrator,
    43	  });
    44	  await hal.start(0);
    45	  servers.push(hal);
    46	  const {port} = hal.server.address() as AddressInfo;
    47	  return `ws://127.0.0.1:${port}/hal/ws`;
    48	};
    49	
    50	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
    51	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    52	  clients.push(client);
    53	  const frames: Frame[] = [];
    54	  let connected: Frame = {type: ''};
    55	  await new Promise<void>(resolve => {
    56	    client.on('message', raw => {
    57	      const frame = JSON.parse(String(raw)) as Frame;
    58	      if (frame.type !== 'connected') {
    59	        if (frame.type === 'pong') resolve();
    60	        else frames.push(frame);
    61	        return;
    62	      }
    63	      connected = frame;
    64	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
    65	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    66	    });
    67	  });
    68	  return {connected, frames};
    69	};
    70	
    71	describe('listing conversations over the WebSocket protocol', () => {
    72	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    73	    const inner = new InMemorySessionStore();
    74	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    75	    const summaries: SessionSummary[] = [
    76	      {
    77	        sessionId: 's2',
    78	        createdAt: new Date('2026-01-01T00:00:00.000Z'),
    79	        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
    80	        entryCount: 4,
    81	      },
    82	    ];
    83	    const store: SessionStore = {
    84	      ...delegatingTo(inner),
    85	      listFor: (userId, options) => {
    86	        seen.push({userId, options});
    87	        return summaries;
    88	      },
    89	    };
    90	    const url = await startEngine(store, 'u1');
    91	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    92	
    93	    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
    94	
    95	    expect({seen, frames}).toEqual({
    96	      seen: [{userId: 'u1', options: {limit: 10, before}}],
    97	      frames: [
    98	        {
    99	          type: 'session_list',
   100	          sessions: [
   101	            {
   102	              sessionId: 's2',
   103	              createdAt: '2026-01-01T00:00:00.000Z',
   104	              updatedAt: '2026-01-01T00:02:00.000Z',
   105	              entryCount: 4,
   106	            },
   107	          ],
   108	        },
   109	      ],
   110	    });
   111	  });
   112	
   113	  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
   114	    const inner = new InMemorySessionStore();
   115	    const withoutList = await startEngine(delegatingTo(inner));
   116	    const failingList = await startEngine({
   117	      ...delegatingTo(inner),
   118	      listFor: () => Promise.reject(new Error('database offline')),
   119	    });
   120	
   121	    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
   122	    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});
   123	
   124	    expect({
   125	      unimplemented: unimplemented.frames,
   126	      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
   127	      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
   128	    }).toEqual({
   129	      unimplemented: [{type: 'session_list', sessions: []}],
   130	      failed: [{type: 'error', code: 'SERVER_ERROR'}],
   131	      logged: [
   132	        {
   133	          level: 'error',
   134	          category: 'ws',
   135	          message: expect.any(String),
   136	          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
   137	        },
   138	      ],
   139	    });
   140	  });
   141	
   142	  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
   143	    const inner = new InMemorySessionStore();
   144	    let calls = 0;
   145	    const store: SessionStore = {
   146	      ...delegatingTo(inner),
   147	      listFor: () => {
   148	        calls += 1;
   149	        return [];
   150	      },
   151	    };
   152	    const url = await startEngine(store);
   153	    const badFrames = [
   154	      {type: 'list_sessions', limit: 'ten'},
   155	      {type: 'list_sessions', limit: -1},
   156	      {type: 'list_sessions', limit: 1.5},
   157	      {type: 'list_sessions', before: 'not-an-object'},
   158	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
   159	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
   160	      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
   161	      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
   162	    ];
   163	
   164	    const codes: Array<string | undefined> = [];
   165	    for (const bad of badFrames) {
   166	      const {frames} = await askAfterConnect(url, bad);
   167	      codes.push(frames[0]?.code);
   168	    }
   169	    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});
   170	
   171	    expect({codes, accepted, calls}).toEqual({
   172	      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
   173	      accepted: [{type: 'session_list', sessions: []}],
   174	      calls: 1,
   175	    });
   176	  });
   177	});
