  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && !(Number.isInteger(message.limit) && (message.limit as number) >= 0)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  if (message.before !== undefined && !isCursor(message.before)) {
    return {valid: false, error: 'list_sessions before must be a sessionId of 1-128 characters and an updatedAt date'};
  }
  const before = message.before as Record<string, unknown> | undefined;
  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit: message.limit as number | undefined,
      before: before && {updatedAt: before.updatedAt as string, sessionId: before.sessionId as string},
    },
  };
}

function isCursor(value: unknown): value is ConversationCursor {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const cursor = value as Record<string, unknown>;
  return (
    typeof cursor.sessionId === 'string' &&
    cursor.sessionId.length >= 1 &&
    cursor.sessionId.length <= 128 &&
    typeof cursor.updatedAt === 'string' &&
    !Number.isNaN(Date.parse(cursor.updatedAt))
  );
}

